package org.thymeleaf.spring6.view;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.PrintWriter;
import java.io.StringWriter;
import java.lang.reflect.Proxy;
import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

import jakarta.servlet.ServletContext;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

import org.junit.jupiter.api.Test;
import org.springframework.web.context.support.StaticWebApplicationContext;
import org.springframework.web.servlet.DispatcherServlet;
import org.thymeleaf.spring6.SpringTemplateEngine;
import org.thymeleaf.templateresolver.StringTemplateResolver;

class ThymeleafViewRenderFragmentTests {

    @Test
    void renderWithoutExplicitMarkupSelectorProcessesTheWholeTemplateAndUsesModel() throws Exception {
        StringTemplateResolver templateResolver = new StringTemplateResolver();
        SpringTemplateEngine templateEngine = new SpringTemplateEngine();
        templateEngine.setTemplateResolver(templateResolver);

        ServletContext servletContext = proxy(ServletContext.class, new HashMap<>());

        StaticWebApplicationContext applicationContext = new StaticWebApplicationContext();
        applicationContext.setServletContext(servletContext);
        applicationContext.refresh();

        HttpServletRequest request = proxy(
                HttpServletRequest.class,
                new HashMap<>(),
                servletContext);
        request.setAttribute(
                DispatcherServlet.WEB_APPLICATION_CONTEXT_ATTRIBUTE,
                applicationContext);

        ResponseState responseState = new ResponseState();
        HttpServletResponse response = proxy(HttpServletResponse.class, responseState);

        TestThymeleafView view = new TestThymeleafView("[[${greeting}]], [[${name}]]");
        view.setServletContext(servletContext);
        view.setApplicationContext(applicationContext);
        view.setTemplateEngine(templateEngine);
        view.setLocale(Locale.US);
        view.setContentType("text/plain");
        view.setCharacterEncoding("UTF-8");
        view.setForceContentType(true);

        Map<String, Object> model = new HashMap<>();
        model.put("greeting", "Hello");
        model.put("name", "Ada");

        view.renderWholeTemplate(model, request, response);

        responseState.writer.flush();
        assertEquals("Hello, Ada", responseState.content.toString());
        assertEquals(Locale.US, responseState.locale);
        assertEquals("text/plain", responseState.contentType);
    }

    private static final class TestThymeleafView extends ThymeleafView {

        private TestThymeleafView(final String templateName) {
            super(templateName);
        }

        private void renderWholeTemplate(
                final Map<String, ?> model,
                final HttpServletRequest request,
                final HttpServletResponse response)
                throws Exception {
            renderFragment(Collections.emptySet(), model, request, response);
        }
    }

    @SuppressWarnings("unchecked")
    private static <T> T proxy(final Class<T> type, final Map<String, Object> attributes) {
        return proxy(type, attributes, null);
    }

    @SuppressWarnings("unchecked")
    private static <T> T proxy(
            final Class<T> type,
            final Map<String, Object> attributes,
            final ServletContext requestServletContext) {
        return (T) Proxy.newProxyInstance(
                type.getClassLoader(),
                new Class<?>[] {type},
                (proxy, method, args) -> {
                    String name = method.getName();

                    if ("getAttribute".equals(name)) {
                        return attributes.get(args[0]);
                    }
                    if ("setAttribute".equals(name)) {
                        attributes.put((String) args[0], args[1]);
                        return null;
                    }
                    if ("removeAttribute".equals(name)) {
                        attributes.remove(args[0]);
                        return null;
                    }
                    if ("getAttributeNames".equals(name)) {
                        return Collections.enumeration(attributes.keySet());
                    }
                    if ("getInitParameter".equals(name)) {
                        return null;
                    }
                    if ("getInitParameterNames".equals(name)) {
                        return Collections.emptyEnumeration();
                    }
                    if ("getServletContext".equals(name)
                            && type == HttpServletRequest.class) {
                        return requestServletContext;
                    }
                    if ("getLocale".equals(name)) {
                        return Locale.US;
                    }
                    if ("getLocales".equals(name)) {
                        return Collections.enumeration(Collections.singleton(Locale.US));
                    }

                    return defaultValue(method.getReturnType());
                });
    }

    @SuppressWarnings("unchecked")
    private static <T> T proxy(final Class<T> type, final ResponseState state) {
        return (T) Proxy.newProxyInstance(
                type.getClassLoader(),
                new Class<?>[] {type},
                (proxy, method, args) -> {
                    String name = method.getName();

                    if ("getWriter".equals(name)) {
                        return state.writer;
                    }
                    if ("setCharacterEncoding".equals(name)) {
                        state.characterEncoding = (String) args[0];
                        return null;
                    }
                    if ("getCharacterEncoding".equals(name)) {
                        return state.characterEncoding;
                    }
                    if ("setContentType".equals(name)) {
                        state.contentType = (String) args[0];
                        return null;
                    }
                    if ("getContentType".equals(name)) {
                        return state.contentType;
                    }
                    if ("setLocale".equals(name)) {
                        state.locale = (Locale) args[0];
                        return null;
                    }
                    if ("getLocale".equals(name)) {
                        return state.locale;
                    }

                    return defaultValue(method.getReturnType());
                });
    }

    private static Object defaultValue(final Class<?> type) {
        if (!type.isPrimitive()) {
            return null;
        }
        if (type == boolean.class) {
            return false;
        }
        if (type == byte.class) {
            return (byte) 0;
        }
        if (type == short.class) {
            return (short) 0;
        }
        if (type == int.class) {
            return 0;
        }
        if (type == long.class) {
            return 0L;
        }
        if (type == float.class) {
            return 0.0f;
        }
        if (type == double.class) {
            return 0.0d;
        }
        if (type == char.class) {
            return '\0';
        }
        return null;
    }

    private static final class ResponseState {
        private final StringWriter content = new StringWriter();
        private final PrintWriter writer = new PrintWriter(content);
        private String characterEncoding;
        private String contentType;
        private Locale locale;
    }
}

