Model(final IModel model) {

        super();

        Validate.notNull(model, "Model cannot be null");

        this.configuration = model.getConfiguration();
        this.templateMode = model.getTemplateMode();

        if (model instanceof Model) {

            final Model mmodel = (Model) model;
            this.queue = mmodel.queue.clone();
            this.queueSize = mmodel.queueSize;

        } else if (model instanceof TemplateModel) {

            final TemplateModel templateModel = (TemplateModel) model;
            this.queue = new IEngineTemplateEvent[templateModel.queue.length + INITIAL_EVENT_QUEUE_SIZE/2];
            System.arraycopy(templateModel.queue, 1, this.queue, 0, templateModel.queue.length - 2);
            this.queueSize = templateModel.queue.length - 2;

        } else {

            this.queue = new IEngineTemplateEvent[INITIAL_EVENT_QUEUE_SIZE];
            Arrays.fill(this.queue, null);
            this.queueSize = 0;
            insertModel(0, model);

        }

    }

// Meant to be called only from within the engine
static OpenElementTag asEngineOpenElementTag(final IOpenElementTag openElementTag) {

        if (openElementTag instanceof OpenElementTag) {
            return (OpenElementTag) openElementTag;
        }


        final IAttribute[] originalAttributeArray = openElementTag.getAllAttributes();

        final Attributes attributes;
        if (originalAttributeArray == null || originalAttributeArray.length == 0) {
            attributes = null;
        } else {
            // We will perform a deep cloning of the attributes into objects of the Attribute class, so that
            // we make sure absolutely all Attributes in the new event are under the engine's control
            final Attribute[] newAttributeArray = new Attribute[originalAttributeArray.length];
            for (int i = 0; i < originalAttributeArray.length; i++) {
                final IAttribute originalAttribute = originalAttributeArray[i];
                newAttributeArray[i] =
                        new Attribute(
                                originalAttribute.getAttributeDefinition(), originalAttribute.getAttributeCompleteName(),
                                originalAttribute.getOperator(), originalAttribute.getValue(), originalAttribute.getValueQuotes(),
                                originalAttribute.getTemplateName(), originalAttribute.getLine(), originalAttribute.getCol());
            }
            final String[] newInnerWhiteSpaces;
            if (newAttributeArray.length == 1) {
                newInnerWhiteSpaces = Attributes.DEFAULT_WHITE_SPACE_ARRAY;
            } else {
                newInnerWhiteSpaces = new String[newAttributeArray.length];
                Arrays.fill(newInnerWhiteSpaces, Attributes.DEFAULT_WHITE_SPACE);
            }
            attributes = new Attributes(newAttributeArray, newInnerWhiteSpaces);
        }

        return new OpenElementTag(
                openElementTag.getTemplateMode(), openElementTag.getElementDefinition(), openElementTag.getElementCompleteName(),
                attributes, openElementTag.isSynthetic(),
                openElementTag.getTemplateName(), openElementTag.getLine(), openElementTag.getCol());

    }

OpenElementTagModelProcessable(
            final OpenElementTag openElementTag, final ProcessorExecutionVars vars,
            final TemplateModelController modelController, final TemplateFlowController flowController,
            final ProcessorTemplateHandler processorTemplateHandler, final ITemplateHandler nextTemplateHandler) {
        super();
        this.openElementTag = openElementTag;
        this.vars = vars;
        this.flowController = flowController;
        this.modelController = modelController;
        this.processorTemplateHandler = processorTemplateHandler;
        this.nextTemplateHandler = nextTemplateHandler;
        this.beforeProcessed = false;
        this.delegationProcessed = false;
        this.afterProcessed = false;
        this.offset = 0;
    }

ProcessorExecutionVars() {
        super();
        this.processorIterator = new ElementProcessorIterator();
    }

/*
     * This will be called by any handleX() methods (only when throttling is enabled) whenever they have to execute
     * work that might potentially get stopped and therefore be left in the pending queue.
     */
private void queueProcessable(final IEngineProcessable processableModel) {

        ensurePendingCapacity();

        final TemplateFlowController controller = this.flowController;

        this.pendingProcessings[this.pendingProcessingsSize] = processableModel;
        this.pendingProcessingsSize++;

        if (controller.stopProcessing) {
            controller.processorTemplateHandlerPending = true;
            return;
        }

        final boolean processed = this.pendingProcessings[this.pendingProcessingsSize - 1].process();
        if (!processed) {
            controller.processorTemplateHandlerPending = true;
            return;
        }
        this.pendingProcessingsSize--;

        controller.processorTemplateHandlerPending = false;

    }

/*
     * This method will be called for any event that arrives from a previous handler in the chain (or the parser, cache...)
     * when the execution has already been stopped and we (potentially) have some work pending. The idea is to queue
     * these events at the end of the pending queue (i.e. at level 0) so that they are processed normally once all
     * pending work has been processed too.
     *
     * Given the cache/parser are immediately stopped once we receive a stop signal, this can only happen if a
     * pre-processor sits in the middle and produces several "sister" events to the one which handling was
     * originally stopped.
     *
     * Also note events used here should always come from previous handlers and never from the execution of pending work
     * itself, given all pending-work structures (i.e. all implementations of IEngineProcessable) should check
     * the "stopProcessing" flag before executing each event, so they should never produce additional pending events
     * that would potentially (and erroneously) be queued at level 0.
     */
private void queueEvent(final ITemplateEvent event) {

        final SimpleModelProcessable pendingProcessableModel;
        if (this.pendingProcessingsSize > 0) {
            final IEngineProcessable level0Pending = this.pendingProcessings[0];
            if (level0Pending instanceof SimpleModelProcessable && ((SimpleModelProcessable)level0Pending).getModelHandler() == this) {
                pendingProcessableModel = (SimpleModelProcessable)level0Pending;
            } else {
                final Model model = new Model(this.configuration, this.templateMode);
                pendingProcessableModel = new SimpleModelProcessable(model, this, this.flowController);
                ensurePendingCapacity();
                System.arraycopy(this.pendingProcessings, 0, this.pendingProcessings, 1, this.pendingProcessingsSize);
                this.pendingProcessings[0] = pendingProcessableModel;
                this.pendingProcessingsSize++;
            }
        } else {
            final Model model = new Model(this.configuration, this.templateMode);
            pendingProcessableModel = new SimpleModelProcessable(model, this, this.flowController);
            ensurePendingCapacity();
            this.pendingProcessings[0] = pendingProcessableModel;
            this.pendingProcessingsSize++;
        }
        pendingProcessableModel.getModel().add(event);
        this.flowController.processorTemplateHandlerPending = true;

    }

private IGatheringModelProcessable obtainCurrentGatheringModel() {
        final IGatheringModelProcessable gatheringModel = this.currentGatheringModel;
        this.currentGatheringModel = null;
        return gatheringModel;
    }

private Model resetModel(final Model model, final boolean createIfNull) {
        if (model == null) {
            if (createIfNull) {
                return new Model(this.configuration, this.templateMode);
            }
            return model;
        }
        model.reset();
        return model;
    }

Text(final CharSequence text) {
        super(text);
    }

/**
     *
     * @since 3.0.0
     *
     * @param message The message of the exception
     * @param templateName The name of the template for which the exception is thrown
     * @param line line position of the event that caused the exception
     * @param col columns position of the event that caused the exception
     */
public TemplateProcessingException(
            final String message, final String templateName, final int line, final int col) {
        super(message);
        this.templateName = templateName;
        this.line = (line < 0? null : Integer.valueOf(line));
        this.col = (col < 0? null : Integer.valueOf(col));
    }

