                vars.modelAfter = resetModel(vars.modelAfter, true);
                vars.modelAfter.addModel(processedModel);
                vars.modelAfterProcessable = true;
                vars.discardEvent = true;
                vars.skipBody = SkipBody.SKIP_ALL;
                vars.skipCloseTag = true;
